long below(long first, long second) {
    return first < second;
}

long signed_below(long first, long second) {
    return first < second;
}

unsigned long unsigned_below(unsigned long first, unsigned long second) {
    return first < second;
}

unsigned long warning(unsigned long fuel, unsigned long reserve) {
    return fuel < reserve;
}

long maximum(long left, long right) {
    if (left >= right) return left;
    return right;
}

unsigned long total_below(unsigned long limit) {
    unsigned long total = 0;
    for (unsigned long i = 0; i < limit; ++i) {
        total += i;
    }
    return total;
}

unsigned long dim(unsigned long brightness, unsigned long ticks) {
    while (ticks != 0) {
        brightness >>= 1;
        --ticks;
    }
    return brightness;
}

unsigned long post_test_visits(unsigned long limit) {
    unsigned long visits = 0;
    do {
        ++visits;
    } while (visits < limit);
    return visits;
}

unsigned long dim_until_dark(unsigned long brightness, unsigned long ticks) {
    while (ticks != 0 && brightness != 0) {
        brightness >>= 1;
        --ticks;
    }
    return brightness;
}

unsigned long sample(unsigned int *samples, unsigned long index) {
    return samples[index];
}

unsigned long sum(unsigned int *samples, unsigned long count) {
    unsigned long total = 0;
    for (unsigned long i = 0; i < count; ++i) {
        total += samples[i];
    }
    return total;
}

unsigned long bounded_length(unsigned char *bytes, unsigned long capacity) {
    unsigned long count = 0;
    while (count < capacity && bytes[count] != 0) {
        ++count;
    }
    return count;
}
